import React, { useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { UserRound, WalletCards, Trophy, BookOpenText, Images, ShieldCheck, Save, UploadCloud, Plus, Trash2, MapPin, Headphones, LoaderCircle, Compass, Mountain, TentTree, Route, Star, ChevronLeft, Sparkles, CalendarDays, BadgeCheck, Leaf, Camera, ArrowUpLeft, LockKeyhole, Medal, Crown, CheckCircle2, Settings2, Bell, MonitorCog, Languages, BriefcaseBusiness, HeartPulse, FileBadge, Backpack, LayoutDashboard, Plane, TrendingUp, CircleGauge } from 'lucide-react';
import { profileApi, type TravelProfile } from '../api/profile';
import type { AuthUser } from '../api/auth';

type Tab = 'overview' | 'identity' | 'finance' | 'wallet' | 'club' | 'stories' | 'media' | 'privacy' | 'settings';
const nav: Array<{ id: Tab; label: string; hint: string; icon: React.ElementType }> = [
  { id: 'overview', label: 'نمای کلی', hint: 'مرکز فرمان سفر', icon: LayoutDashboard }, { id: 'identity', label: 'هویت سفر', hint: 'پاسپورت همسفر', icon: UserRound }, { id: 'finance', label: 'مرکز مالی سفر', hint: 'کیف پول و تسویه', icon: WalletCards },
  { id: 'club', label: 'باشگاه فرندلی', hint: 'امتیاز و مزایا', icon: Trophy }, { id: 'stories', label: 'سفرنامه‌ها', hint: 'روایت تجربه‌ها', icon: BookOpenText },
  { id: 'media', label: 'استودیوی سفر', hint: 'عکس و پادکست', icon: Images }, { id: 'privacy', label: 'اعتماد و ایمنی', hint: 'حریم خصوصی', icon: ShieldCheck }, { id: 'settings', label: 'تنظیمات', hint: 'تجربه و اعلان‌ها', icon: Settings2 }
];
const interestOptions = ['کمپینگ', 'کوهنوردی', 'جنگل‌نوردی', 'کویر', 'عکاسی سفر', 'سفر خانوادگی', 'دوچرخه‌سواری', 'پرنده‌نگری'];

export const UserProfileModal: React.FC<{ isOpen: boolean; onClose: () => void; onRequireAuth: () => void }> = ({ isOpen, onClose, onRequireAuth }) => {
  const [tab, setTab] = useState<Tab>('overview'); const [profile, setProfile] = useState<TravelProfile | null>(null); const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(false); const [saving, setSaving] = useState(false); const [notice, setNotice] = useState<{type:'ok'|'error';text:string}|null>(null);
  const [story, setStory] = useState({ title: '', destination: '', date: '', body: '' }); const [mediaTitle, setMediaTitle] = useState(''); const [mediaFile, setMediaFile] = useState<File | null>(null);
  useEffect(() => { if (!isOpen) return; setLoading(true); profileApi.get().then(data => { setProfile(data.profile); setUser(data.user); }).catch(error => { setNotice({type:'error',text:error.message}); if (error.message.includes('وارد')) onRequireAuth(); }).finally(() => setLoading(false)); }, [isOpen, onRequireAuth]);
  const completion = useMemo(() => !profile ? 0 : Math.round(([profile.bio, profile.city, profile.birthDate, profile.emergencyContact, profile.interests.length, profile.dietaryNotes].filter(Boolean).length / 6) * 100), [profile]);
  if (!isOpen) return null;
  const update = <K extends keyof TravelProfile>(key: K, value: TravelProfile[K]) => profile && setProfile({ ...profile, [key]: value });
  const save = async (next = profile) => { if (!next) return; setSaving(true); setNotice(null); try { const result=await profileApi.save(next); setProfile(result.profile); setNotice({type:'ok',text:'همه تغییرات با موفقیت ذخیره شد.'}); } catch(error) { setNotice({type:'error',text:error instanceof Error?error.message:'ذخیره ناموفق بود.'}); } finally { setSaving(false); } };
  const addStory = async () => { if (!profile || story.title.trim().length<2 || story.body.trim().length<10) return setNotice({type:'error',text:'عنوان و متن کامل سفرنامه الزامی است.'}); const next={...profile,stories:[{...story,id:crypto.randomUUID(),createdAt:new Date().toISOString()},...profile.stories]}; setProfile(next); setStory({title:'',destination:'',date:'',body:''}); await save(next); };
  const upload = async () => { if(!profile||!mediaFile||!mediaTitle.trim()) return setNotice({type:'error',text:'عنوان و فایل را انتخاب کنید.'}); setSaving(true); try { const file=await profileApi.upload(mediaFile); const next:TravelProfile={...profile,media:[{id:crypto.randomUUID(),kind:mediaFile.type.startsWith('audio/')?'podcast':'photo',title:mediaTitle,url:file.url,mimeType:file.mimeType,createdAt:new Date().toISOString()},...profile.media]}; setProfile(next);setMediaFile(null);setMediaTitle('');await save(next);}catch(error){setNotice({type:'error',text:error instanceof Error?error.message:'آپلود ناموفق بود.'});}finally{setSaving(false);} };
  const active = nav.find(item=>item.id===tab)!;

  return <div className="min-h-screen bg-[#061417] p-0 sm:p-3 lg:p-6">
    <div className="relative mx-auto min-h-screen max-w-[1500px] overflow-hidden bg-[#f3f6f3] sm:min-h-[calc(100vh-1.5rem)] sm:rounded-[32px] lg:min-h-[calc(100vh-3rem)] shadow-[0_40px_120px_rgba(0,0,0,.5)]" dir="rtl">
      <button onClick={onClose} aria-label="بازگشت به صفحه اصلی" title="بازگشت به صفحه اصلی" className="absolute left-4 top-4 z-50 grid h-11 w-11 place-items-center rounded-2xl bg-white/90 text-slate-700 shadow-xl backdrop-blur transition hover:-translate-x-1"><ArrowUpLeft/></button>
      {loading ? <div className="min-h-[90vh] grid place-items-center"><div className="text-center"><LoaderCircle className="mx-auto animate-spin text-emerald-700" size={42}/><p className="mt-3 text-sm font-bold text-slate-500">در حال ساخت فضای شخصی سفر شما…</p></div></div> : profile && <>
        <section className="relative overflow-hidden bg-[#0d4038] text-white">
          <img src="/motion/hero-forest.gif" data-motion="off" alt="چشم‌انداز کمپ" className="absolute inset-0 h-full w-full object-cover opacity-25"/>
          <div className="absolute inset-0 bg-gradient-to-l from-[#092f2b] via-[#0d4038]/90 to-[#0d4038]/40"/>
          <div className="relative px-5 py-7 sm:px-10 lg:px-14 lg:py-10"><div className="flex flex-col lg:flex-row lg:items-end justify-between gap-7">
            <div className="flex items-center gap-5"><div className="relative"><div className="grid h-24 w-24 sm:h-28 sm:w-28 place-items-center rounded-[30px] border-4 border-white/20 bg-lime-300 text-4xl font-black text-emerald-950 shadow-2xl">{user?.fullName?.slice(0,1)||'ه'}</div><span className="absolute -bottom-2 -left-2 grid h-9 w-9 place-items-center rounded-full bg-emerald-600 ring-4 ring-[#0d4038]"><BadgeCheck size={20}/></span></div><div><div className="flex items-center gap-2 text-xs font-bold text-lime-300"><Compass size={15}/>TRAVEL IDENTITY · FC-{user?.id?.slice(0,6).toUpperCase()}</div><h1 className="mt-2 text-3xl sm:text-4xl font-black">{user?.fullName}</h1><p className="mt-2 text-sm text-white/65">{profile.travelStyle} · {profile.experienceLevel} · {profile.city||'موقعیت ثبت نشده'}</p><div className="mt-4 flex flex-wrap gap-2">{profile.interests.slice(0,4).map(item=><span key={item} className="rounded-full border border-white/15 bg-white/10 px-3 py-1 text-xs">{item}</span>)}</div></div></div>
            <div className="grid grid-cols-3 gap-2 sm:gap-3"><HeroMetric value={`${completion}٪`} label="تکمیل هویت"/><HeroMetric value={profile.club.points.toLocaleString('fa-IR')} label="امتیاز باشگاه"/><HeroMetric value={String(profile.stories.length+profile.media.length)} label="خاطره ثبت‌شده"/></div>
          </div></div>
        </section>

        <div className="sticky top-0 z-30 border-b border-white/60 bg-[#f8fbf8]/85 px-3 shadow-[0_12px_40px_rgba(15,54,47,.08)] backdrop-blur-2xl sm:px-8"><nav className="profile-tabs mx-auto flex max-w-7xl gap-2 overflow-x-auto py-3" aria-label="بخش‌های پروفایل">{nav.map((item,index)=>{const selected=tab===item.id;return <motion.button key={item.id} onClick={()=>setTab(item.id)} whileHover={{y:-2}} whileTap={{scale:.97}} className={`group relative flex min-w-fit items-center gap-3 overflow-hidden rounded-2xl px-4 py-3.5 text-right transition-colors ${selected?'text-white':'text-slate-500 hover:bg-white hover:text-slate-900 hover:shadow-md'}`}>{selected&&<motion.span layoutId="active-profile-tab" className="absolute inset-0 rounded-2xl bg-gradient-to-l from-[#0b5146] to-[#123f37] shadow-lg shadow-emerald-950/20" transition={{type:'spring',stiffness:380,damping:32}}/>}<span className={`relative grid h-9 w-9 place-items-center rounded-xl transition ${selected?'bg-lime-300 text-emerald-950':'bg-slate-100 text-slate-500 group-hover:bg-emerald-50 group-hover:text-emerald-700'}`}><item.icon size={18}/></span><span className="relative"><b className="block text-xs sm:text-sm">{item.label}</b><small className={`hidden text-[10px] sm:block ${selected?'text-white/55':'text-slate-400'}`}>{item.hint}</small></span><span className={`relative mr-1 text-[9px] font-mono ${selected?'text-lime-300':'text-slate-300'}`}>{String(index+1).padStart(2,'0')}</span></motion.button>})}</nav></div>

        <main className="mx-auto max-w-7xl p-4 sm:p-7 lg:p-10">
          <header className="mb-7 flex flex-wrap items-center justify-between gap-4"><div><p className="flex items-center gap-2 text-xs font-black text-emerald-700"><Sparkles size={15}/>{active.hint}</p><h2 className="mt-1 text-2xl sm:text-3xl font-black text-slate-900">{active.label}</h2></div>{!['wallet','finance','club'].includes(tab)&&<button onClick={()=>save()} disabled={saving} className="flex items-center gap-2 rounded-2xl bg-[#123f37] px-6 py-3 text-sm font-black text-white shadow-lg shadow-emerald-900/15 hover:-translate-y-0.5 disabled:opacity-50 transition">{saving?<LoaderCircle className="animate-spin" size={18}/>:<Save size={18}/>}ذخیره امن تغییرات</button>}</header>
          {notice&&<div role="status" className={`mb-6 flex items-center gap-2 rounded-2xl border p-4 text-sm font-bold ${notice.type==='ok'?'border-emerald-200 bg-emerald-50 text-emerald-800':'border-rose-200 bg-rose-50 text-rose-700'}`}>{notice.type==='ok'?<CheckCircle2/>:<ShieldCheck/>}{notice.text}</div>}

          <AnimatePresence mode="wait"><motion.div key={tab} initial={{opacity:0,y:18,filter:'blur(5px)'}} animate={{opacity:1,y:0,filter:'blur(0px)'}} exit={{opacity:0,y:-10,filter:'blur(4px)'}} transition={{duration:.32,ease:[.22,1,.36,1]}}>
          {tab==='overview'&&<ProfileOverview profile={profile} user={user} completion={completion} onNavigate={setTab}/>} 

          {tab==='finance'&&<WalletWorkspace profile={profile} onChange={next=>setProfile({...profile,wallet:next})} onNotice={setNotice}/>} 
          {tab==='settings'&&<SettingsWorkspace settings={profile.settings} onChange={settings=>update('settings',settings)}/>} 
          {tab==='identity'&&<ProfessionalProfile professional={profile.professional} onChange={professional=>update('professional',professional)}/>} 

          {tab==='identity'&&<div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><section className="rounded-[28px] border border-slate-200 bg-white p-5 sm:p-7 shadow-sm"><SectionTitle icon={UserRound} title="پاسپورت دیجیتال همسفر" subtitle="اطلاعات پایه برای پیشنهاد سفر و هماهنگی ایمن"/><div className="mt-6 grid gap-5 md:grid-cols-2"><Field label="نام کامل" value={user?.fullName||''} disabled/><Field label="شماره همراه تأییدشده" value={user?.phone||''} disabled/><Field label="شهر محل سکونت" value={profile.city} onChange={value=>update('city',value)} icon={MapPin}/><Field label="تاریخ تولد" value={profile.birthDate} onChange={value=>update('birthDate',value)} type="date" icon={CalendarDays}/><Select label="سبک اصلی سفر" value={profile.travelStyle} options={['طبیعت‌گردی','کمپینگ','ماجراجویی','خانوادگی','لوکس مسئولانه']} onChange={value=>update('travelStyle',value)}/><Select label="سطح تجربه" value={profile.experienceLevel} options={['مبتدی','نیمه‌حرفه‌ای','حرفه‌ای','راهنمای سفر']} onChange={value=>update('experienceLevel',value)}/><Field label="تماس اضطراری" value={profile.emergencyContact} onChange={value=>update('emergencyContact',value)} icon={ShieldCheck}/><Field label="ملاحظات غذایی و پزشکی" value={profile.dietaryNotes} onChange={value=>update('dietaryNotes',value)} icon={Leaf}/></div><label className="mt-5 block text-xs font-black text-slate-600">داستان کوتاه من<textarea value={profile.bio} onChange={event=>update('bio',event.target.value)} rows={4} maxLength={1000} placeholder="تجربه، روحیه و انتظارتان از یک همسفر خوب را بنویسید…" className="mt-2 w-full rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm outline-none focus:border-emerald-600 focus:bg-white"/></label></section><aside className="space-y-6"><div className="rounded-[28px] bg-gradient-to-br from-amber-100 to-lime-100 p-6"><SectionTitle icon={Mountain} title="DNA سفر شما" subtitle="علایق برای پیشنهادهای دقیق‌تر"/><div className="mt-5 flex flex-wrap gap-2">{interestOptions.map(item=><button key={item} onClick={()=>update('interests',profile.interests.includes(item)?profile.interests.filter(v=>v!==item):[...profile.interests,item])} className={`rounded-full border px-3.5 py-2 text-xs font-bold transition ${profile.interests.includes(item)?'border-emerald-800 bg-emerald-800 text-white':'border-white bg-white/70 text-slate-600 hover:border-emerald-400'}`}>{item}</button>)}</div></div><div className="rounded-[28px] bg-[#102b35] p-6 text-white"><p className="text-xs text-cyan-300">TRAVEL READINESS</p><h3 className="mt-2 text-xl font-black">آمادگی سفر {completion}٪</h3><div className="mt-4 h-3 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-gradient-to-l from-lime-300 to-emerald-400" style={{width:`${completion}%`}}/></div><p className="mt-4 text-xs leading-6 text-white/60">تکمیل اطلاعات پزشکی و تماس اضطراری، هماهنگی لیدر تور را سریع‌تر می‌کند.</p></div></aside></div>}

          {tab==='wallet'&&<div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><section className="relative overflow-hidden rounded-[30px] bg-gradient-to-br from-[#092f2b] via-[#0c5547] to-[#1c7760] p-7 text-white shadow-2xl"><div className="absolute -left-16 -top-16 h-56 w-56 rounded-full bg-lime-300/15 blur-2xl"/><div className="relative"><div className="flex justify-between"><WalletCards className="text-lime-300" size={32}/><span className="rounded-full bg-white/10 px-3 py-1 text-xs">FC TRAVEL WALLET</span></div><p className="mt-12 text-sm text-white/55">موجودی قابل استفاده</p><p className="mt-2 text-4xl font-black">{profile.wallet.balance.toLocaleString('fa-IR')} <small className="text-base">تومان</small></p><div className="mt-10 flex justify-between border-t border-white/10 pt-5 text-xs text-white/60"><span>{user?.fullName}</span><span>•••• {user?.id.slice(-4).toUpperCase()}</span></div></div></section><section className="rounded-[28px] border bg-white p-6"><SectionTitle icon={Route} title="جریان مالی سفر" subtitle="سوابق اعتبار، پرداخت و بازگشت وجه"/><Empty show={!profile.wallet.transactions.length} icon={WalletCards} title="هنوز تراکنشی ندارید" text="پس از رزرو یا شارژ معتبر، گردش مالی اینجا نمایش داده می‌شود."/>{profile.wallet.transactions.map(tx=><div key={tx.id} className="mt-3 flex items-center justify-between rounded-2xl border p-4"><span><b>{tx.title}</b><small className="block text-slate-400">{tx.date}</small></span><b className={tx.type==='credit'?'text-emerald-600':'text-rose-600'}>{tx.amount.toLocaleString('fa-IR')}</b></div>)}</section></div>}

          {tab==='club'&&<div className="space-y-6"><section className="relative overflow-hidden rounded-[32px] bg-[#111d2c] p-6 sm:p-9 text-white"><div className="absolute left-0 top-0 h-full w-1/2 bg-gradient-to-r from-lime-300/15 to-transparent"/><div className="relative grid gap-8 lg:grid-cols-[1fr_.7fr] lg:items-center"><div><span className="inline-flex items-center gap-2 rounded-full bg-lime-300 px-4 py-2 text-xs font-black text-emerald-950"><Crown size={15}/>FRIENDLY CLUB · {profile.club.tier}</span><h3 className="mt-5 text-3xl font-black">هر سفر، یک قدم به تجربه ویژه‌تر</h3><p className="mt-3 max-w-xl text-sm leading-7 text-white/60">امتیازهای شما از رزرو، ثبت تجربه و سفر مسئولانه محاسبه می‌شوند. سطح بعدی مزایای بیشتری فعال می‌کند.</p><div className="mt-7"><div className="flex justify-between text-xs"><span>{profile.club.points.toLocaleString('fa-IR')} امتیاز</span><span>۱۰۰۰ امتیاز تا نقره‌ای</span></div><div className="mt-2 h-3 overflow-hidden rounded-full bg-white/10"><div className="h-full bg-gradient-to-l from-lime-300 to-amber-300" style={{width:`${Math.min(100,profile.club.points/10)}%`}}/></div></div></div><div className="rounded-[26px] border border-white/10 bg-white/5 p-6 backdrop-blur"><Medal className="text-amber-300" size={38}/><p className="mt-5 text-xs text-white/50">شماره عضویت</p><p className="font-mono text-lg font-black tracking-widest">FC-{user?.id.slice(0,8).toUpperCase()}</p><div className="mt-6 flex items-end justify-between"><div><p className="text-xs text-white/50">عضو</p><b>{user?.fullName}</b></div><span className="rounded-full bg-emerald-500/20 px-3 py-1 text-xs text-emerald-200">فعال</span></div></div></div></section><div className="grid gap-4 md:grid-cols-3"><StatCard icon={Trophy} value={profile.club.points.toLocaleString('fa-IR')} label="امتیاز قابل استفاده" tone="lime"/><StatCard icon={Star} value={profile.club.tier} label="سطح فعلی عضویت" tone="amber"/><StatCard icon={WalletCards} value={String(profile.club.cards.filter(c=>c.status==='فعال').length)} label="کارت و مزیت فعال" tone="cyan"/></div><section className="rounded-[28px] border bg-white p-6"><SectionTitle icon={Sparkles} title="کارت‌ها و مزایای من" subtitle="مزایای فعال‌شده در باشگاه"/><div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{profile.club.cards.map(card=><article key={card.id} className="group rounded-2xl border border-slate-200 bg-slate-50 p-5 hover:-translate-y-1 hover:border-emerald-300 hover:shadow-lg transition"><div className="flex justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl bg-emerald-100 text-emerald-700"><Trophy/></div><span className="text-xs text-emerald-600">{card.status}</span></div><h4 className="mt-5 font-black">{card.title}</h4><p className="mt-1 text-sm text-slate-500">{card.value}</p></article>)}</div></section></div>}

          {tab==='stories'&&<div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><section className="h-fit rounded-[28px] border bg-white p-6"><SectionTitle icon={Plus} title="روایت تازه" subtitle="سفر را به یک تجربه ماندگار تبدیل کنید"/><div className="mt-5 space-y-4"><Field label="عنوان روایت" value={story.title} onChange={v=>setStory({...story,title:v})}/><Field label="مقصد" value={story.destination} onChange={v=>setStory({...story,destination:v})} icon={MapPin}/><Field label="تاریخ سفر" value={story.date} onChange={v=>setStory({...story,date:v})} type="date"/><label className="block text-xs font-black text-slate-600">متن سفرنامه<textarea rows={8} value={story.body} onChange={e=>setStory({...story,body:e.target.value})} className="mt-2 w-full rounded-2xl border bg-slate-50 p-4 text-sm outline-none focus:border-emerald-600"/></label><button onClick={addStory} className="w-full rounded-2xl bg-emerald-700 py-3.5 font-black text-white">انتشار در آرشیو شخصی</button></div></section><section><SectionTitle icon={BookOpenText} title="کتابخانه سفرهای من" subtitle={`${profile.stories.length} روایت ثبت‌شده`}/><Empty show={!profile.stories.length} icon={BookOpenText} title="صفحه اول سفرنامه هنوز سفید است" text="اولین روایت خود را با جزئیات مقصد و تجربه همسفری ثبت کنید."/>{profile.stories.map(item=><article key={item.id} className="mt-4 rounded-[26px] border bg-white p-6 hover:shadow-lg transition"><div className="flex justify-between gap-4"><div><span className="text-xs font-bold text-emerald-600">{item.date||'بدون تاریخ'} · {item.destination||'مقصد آزاد'}</span><h3 className="mt-2 text-xl font-black">{item.title}</h3></div><button onClick={()=>{const next={...profile,stories:profile.stories.filter(v=>v.id!==item.id)};setProfile(next);save(next)}} aria-label="حذف سفرنامه" className="text-slate-300 hover:text-rose-500"><Trash2/></button></div><p className="mt-4 line-clamp-4 text-sm leading-7 text-slate-600">{item.body}</p></article>)}</section></div>}

          {tab==='media'&&<div className="space-y-6"><section className="overflow-hidden rounded-[30px] bg-gradient-to-l from-indigo-950 to-[#0d4038] p-6 sm:p-8 text-white"><div className="grid gap-7 lg:grid-cols-[.7fr_1.3fr] lg:items-center"><div><Camera className="text-lime-300" size={34}/><h3 className="mt-4 text-2xl font-black">استودیوی خاطرات سفر</h3><p className="mt-2 text-sm leading-7 text-white/60">عکس‌ها و صدای مسیر را در آرشیو شخصی خود نگه دارید.</p></div><div className="grid gap-3 sm:grid-cols-2"><input value={mediaTitle} onChange={e=>setMediaTitle(e.target.value)} placeholder="عنوان عکس یا اپیزود" className="rounded-2xl border border-white/15 bg-white/10 px-4 py-3 text-sm outline-none placeholder:text-white/35"/><label className="cursor-pointer rounded-2xl border border-dashed border-lime-300/60 bg-lime-300/10 p-3 text-center text-sm font-bold"><UploadCloud className="inline ml-2" size={18}/>{mediaFile?.name||'انتخاب عکس یا فایل صوتی'}<input type="file" className="hidden" accept="image/jpeg,image/png,image/webp,image/gif,audio/mpeg,audio/mp4,audio/ogg,audio/wav" onChange={e=>setMediaFile(e.target.files?.[0]||null)}/></label><button onClick={upload} disabled={saving} className="sm:col-span-2 rounded-2xl bg-lime-300 py-3 font-black text-emerald-950">ثبت در استودیو</button></div></div></section><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><Empty show={!profile.media.length} icon={Images} title="استودیوی شما آماده است" text="اولین عکس یا پادکست سفر را بارگذاری کنید." wide/>{profile.media.map(item=><article key={item.id} className="overflow-hidden rounded-[24px] border bg-white shadow-sm"><div className="relative h-52 bg-slate-900">{item.kind==='photo'?<img src={item.url} data-motion="off" alt={item.title} className="h-full w-full object-cover"/>:<div className="grid h-full place-items-center bg-gradient-to-br from-indigo-950 to-emerald-900 text-lime-300"><Headphones size={56}/></div>}<span className="absolute right-3 top-3 rounded-full bg-black/50 px-3 py-1 text-[10px] text-white backdrop-blur">{item.kind==='photo'?'PHOTO':'PODCAST'}</span></div><div className="p-5"><h4 className="font-black">{item.title}</h4>{item.kind==='podcast'&&<audio controls preload="metadata" src={item.url} className="mt-3 w-full"/>}<button onClick={()=>{const next={...profile,media:profile.media.filter(v=>v.id!==item.id)};setProfile(next);save(next)}} className="mt-4 text-xs font-bold text-rose-500">حذف رسانه</button></div></article>)}</div></div>}

          {tab==='privacy'&&<div className="grid gap-6 lg:grid-cols-[1fr_.65fr]"><section className="rounded-[28px] border bg-white p-6"><SectionTitle icon={LockKeyhole} title="مرکز اعتماد و حریم خصوصی" subtitle="شما تعیین می‌کنید چه چیزی برای دیگران قابل مشاهده باشد"/><div className="mt-6 space-y-3">{([['profileVisible','پروفایل قابل مشاهده','نام، هویت سفر و علایق برای همسفران تأییدشده نمایش داده شود.'],['showTrips','نمایش سفرنامه‌ها','روایت‌ها و خاطرات منتشرشده در پروفایل عمومی دیده شوند.'],['allowCompanionRequests','درخواست همسفری','اعضای احرازشده بتوانند برای شما درخواست همسفری ارسال کنند.']] as const).map(([key,title,text])=><label key={key} className="flex cursor-pointer items-center justify-between gap-5 rounded-2xl border border-slate-200 p-5 hover:border-emerald-300 transition"><span><b className="block text-sm">{title}</b><small className="mt-1 block leading-6 text-slate-500">{text}</small></span><input type="checkbox" checked={profile.privacy[key]} onChange={e=>update('privacy',{...profile.privacy,[key]:e.target.checked})} className="h-6 w-6 accent-emerald-700"/></label>)}</div></section><aside className="space-y-4"><div className="rounded-[28px] bg-emerald-900 p-6 text-white"><ShieldCheck className="text-lime-300" size={36}/><h3 className="mt-5 text-xl font-black">وضعیت اعتماد: استاندارد</h3><ul className="mt-5 space-y-3 text-xs text-white/70"><li className="flex gap-2"><CheckCircle2 className="text-lime-300" size={17}/>شماره همراه تأیید شده</li><li className="flex gap-2"><CheckCircle2 className="text-lime-300" size={17}/>نشست امن HttpOnly فعال</li><li className="flex gap-2"><CheckCircle2 className="text-lime-300" size={17}/>کنترل نمایش پروفایل فعال</li></ul></div><div className="rounded-[28px] border border-amber-200 bg-amber-50 p-6"><p className="text-xs font-black text-amber-700">تماس اضطراری</p><p className="mt-2 text-lg font-black">{profile.emergencyContact||'تکمیل نشده'}</p><button onClick={()=>setTab('identity')} className="mt-4 flex items-center gap-2 text-xs font-black text-amber-800">تکمیل در هویت سفر<ChevronLeft size={15}/></button></div></aside></div>}
          </motion.div></AnimatePresence>
        </main>
      </>}
    </div>
  </div>;
};

const ProfileOverview=({profile,user,completion,onNavigate}:{profile:TravelProfile;user:AuthUser|null;completion:number;onNavigate:(tab:Tab)=>void})=>{
  const readiness=Math.round((completion+(profile.professional.passportReady?100:0)+(profile.professional.insuranceProvider?100:0)+(profile.professional.languages.length>0?100:0))/4);
  const actions=[{tab:'identity' as Tab,icon:UserRound,title:'تکمیل هویت سفر',text:'اطلاعات شخصی، پزشکی و آمادگی مسیر',tone:'from-emerald-500 to-teal-700'},{tab:'finance' as Tab,icon:WalletCards,title:'مدیریت مالی سفر',text:'کیف پول، تسویه و صورتحساب‌ها',tone:'from-cyan-500 to-blue-700'},{tab:'stories' as Tab,icon:BookOpenText,title:'ثبت تجربه تازه',text:'سفرنامه و آرشیو مسیرهای شما',tone:'from-amber-400 to-orange-600'},{tab:'media' as Tab,icon:Camera,title:'استودیوی خاطرات',text:'عکس‌های سفر و پادکست مسیر',tone:'from-violet-500 to-indigo-700'}];
  const checklist=[{done:Boolean(profile.city&&profile.birthDate),title:'هویت پایه و محل سکونت',tab:'identity' as Tab},{done:Boolean(profile.emergencyContact),title:'تماس اضطراری',tab:'identity' as Tab},{done:Boolean(profile.professional.insuranceProvider),title:'پوشش بیمه سفر',tab:'identity' as Tab},{done:profile.settings.security.loginAlerts,title:'هشدار امنیت ورود',tab:'settings' as Tab}];
  return <div className="space-y-7"><section className="relative overflow-hidden rounded-[34px] bg-[#071e26] p-6 text-white shadow-2xl sm:p-9"><div className="absolute inset-0 opacity-30 [background-image:radial-gradient(circle_at_15%_20%,#84cc16_0,transparent_25%),radial-gradient(circle_at_85%_75%,#06b6d4_0,transparent_28%)]"/><motion.div className="absolute -left-16 -top-16 h-56 w-56 rounded-full border border-lime-300/20" animate={{rotate:360}} transition={{duration:28,repeat:Infinity,ease:'linear'}}/><div className="relative grid gap-8 xl:grid-cols-[1.25fr_.75fr] xl:items-center"><div><span className="inline-flex items-center gap-2 rounded-full border border-lime-300/20 bg-lime-300/10 px-4 py-2 text-xs font-bold text-lime-300"><Plane size={16}/>TRAVEL COMMAND CENTER</span><h2 className="mt-5 text-3xl font-black leading-tight sm:text-5xl">سلام {user?.fullName?.split(' ')[0]}،<br/><span className="bg-gradient-to-l from-lime-300 to-cyan-300 bg-clip-text text-transparent">سفر بعدی از اینجا شروع می‌شود.</span></h2><p className="mt-4 max-w-2xl text-sm leading-7 text-white/55">هویت سفر، آمادگی مسیر، امور مالی و خاطرات شما در یک فضای یکپارچه و امن مدیریت می‌شود.</p><div className="mt-7 flex flex-wrap gap-3"><button onClick={()=>onNavigate('identity')} className="rounded-2xl bg-lime-300 px-6 py-3 text-sm font-black text-emerald-950 shadow-lg shadow-lime-950/30 transition hover:-translate-y-1">تکمیل پرونده سفر</button><button onClick={()=>onNavigate('finance')} className="rounded-2xl border border-white/15 bg-white/5 px-6 py-3 text-sm font-black text-white backdrop-blur transition hover:bg-white/10">مشاهده کیف پول</button></div></div><div className="grid grid-cols-2 gap-3"><OverviewMetric icon={CircleGauge} value={`${readiness}٪`} label="آمادگی سفر" accent="lime"/><OverviewMetric icon={WalletCards} value={profile.wallet.balance.toLocaleString('fa-IR')} label="اعتبار کیف پول" accent="cyan"/><OverviewMetric icon={Trophy} value={profile.club.points.toLocaleString('fa-IR')} label="امتیاز باشگاه" accent="amber"/><OverviewMetric icon={Route} value={String(profile.stories.length)} label="سفرنامه ثبت‌شده" accent="violet"/></div></div></section>
  <section><div className="mb-4 flex items-end justify-between"><div><p className="text-xs font-black text-emerald-700">دسترسی سریع</p><h3 className="mt-1 text-2xl font-black text-slate-900">فضای کاری همسفر</h3></div><span className="hidden text-xs text-slate-400 sm:block">برای ورود به هر بخش انتخاب کنید</span></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{actions.map((action,index)=><motion.button key={action.tab} onClick={()=>onNavigate(action.tab)} initial={{opacity:0,y:20}} animate={{opacity:1,y:0}} transition={{delay:index*.06}} whileHover={{y:-7}} className="group relative overflow-hidden rounded-[26px] border border-slate-200 bg-white p-5 text-right shadow-sm transition-shadow hover:shadow-xl"><span className={`grid h-12 w-12 place-items-center rounded-2xl bg-gradient-to-br ${action.tone} text-white shadow-lg`}><action.icon/></span><h4 className="mt-5 font-black text-slate-900">{action.title}</h4><p className="mt-2 text-xs leading-6 text-slate-400">{action.text}</p><ChevronLeft className="absolute bottom-5 left-5 text-slate-300 transition group-hover:-translate-x-1 group-hover:text-emerald-600" size={19}/></motion.button>)}</div></section>
  <section className="grid gap-6 lg:grid-cols-[1fr_.7fr]"><div className="rounded-[30px] border border-slate-200 bg-white p-6 shadow-sm"><SectionTitle icon={TrendingUp} title="شاخص آمادگی همسفر" subtitle="کنترل موارد ضروری پیش از رزرو برنامه بعدی"/><div className="mt-6 space-y-3">{checklist.map(item=><button key={item.title} onClick={()=>onNavigate(item.tab)} className="flex w-full items-center justify-between rounded-2xl border border-slate-100 bg-slate-50 p-4 text-right transition hover:border-emerald-300 hover:bg-emerald-50/40"><span className="flex items-center gap-3"><span className={`grid h-8 w-8 place-items-center rounded-xl ${item.done?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-700'}`}>{item.done?<CheckCircle2 size={17}/>:<span className="text-xs font-black">!</span>}</span><b className="text-xs text-slate-700">{item.title}</b></span><span className={`text-[10px] font-black ${item.done?'text-emerald-600':'text-amber-600'}`}>{item.done?'تکمیل':'نیازمند اقدام'}</span></button>)}</div></div><div className="relative overflow-hidden rounded-[30px] bg-gradient-to-br from-lime-200 via-emerald-100 to-cyan-100 p-6"><Mountain className="text-emerald-800" size={40}/><p className="mt-8 text-xs font-black text-emerald-700">TRAVEL DNA</p><h3 className="mt-2 text-2xl font-black text-emerald-950">{profile.travelStyle}</h3><p className="mt-2 text-sm text-emerald-900/60">سطح تجربه: {profile.experienceLevel}</p><div className="mt-6 flex flex-wrap gap-2">{profile.interests.length?profile.interests.slice(0,5).map(item=><span key={item} className="rounded-full bg-white/70 px-3 py-2 text-[10px] font-bold text-emerald-800">{item}</span>):<button onClick={()=>onNavigate('identity')} className="rounded-full bg-white/80 px-4 py-2 text-xs font-black text-emerald-800">تعریف علایق سفر +</button>}</div></div></section></div>
};
const OverviewMetric=({icon:Icon,value,label,accent}:{icon:React.ElementType;value:string;label:string;accent:'lime'|'cyan'|'amber'|'violet'})=>{const tones={lime:'text-lime-300 bg-lime-300/10',cyan:'text-cyan-300 bg-cyan-300/10',amber:'text-amber-300 bg-amber-300/10',violet:'text-violet-300 bg-violet-300/10'};return <motion.div whileHover={{scale:1.025}} className="rounded-[24px] border border-white/10 bg-white/[.06] p-4 backdrop-blur-xl"><span className={`grid h-10 w-10 place-items-center rounded-xl ${tones[accent]}`}><Icon size={20}/></span><b className="mt-4 block truncate text-lg sm:text-xl">{value}</b><small className="text-[10px] text-white/45">{label}</small></motion.div>};

const ProfessionalProfile=({professional,onChange}:{professional:TravelProfile['professional'];onChange:(value:TravelProfile['professional'])=>void})=>{
  const set=<K extends keyof TravelProfile['professional']>(key:K,value:TravelProfile['professional'][K])=>onChange({...professional,[key]:value});
  const [language,setLanguage]=useState('');
  return <section className="mb-6 rounded-[28px] border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><SectionTitle icon={FileBadge} title="پرونده حرفه‌ای آمادگی سفر" subtitle="اطلاعات عملیاتی موردنیاز لیدر، بیمه و هماهنگی گروه"/><div className="mt-6 grid gap-5 md:grid-cols-2 xl:grid-cols-3"><Field label="حرفه یا حوزه فعالیت" value={professional.occupation} onChange={value=>set('occupation',value)} icon={BriefcaseBusiness}/><Select label="آمادگی جسمانی" value={professional.fitnessLevel} options={['نیازمند همراهی','سبک','متوسط','آماده','ورزشکار حرفه‌ای']} onChange={value=>set('fitnessLevel',value)}/><Field label="شرکت یا طرح بیمه سفر" value={professional.insuranceProvider} onChange={value=>set('insuranceProvider',value)} icon={HeartPulse}/><Field label="تاریخ پایان اعتبار بیمه" value={professional.insuranceExpiry} onChange={value=>set('insuranceExpiry',value)} type="date" icon={CalendarDays}/><label className="flex cursor-pointer items-center justify-between gap-4 rounded-2xl border border-slate-200 bg-slate-50 p-4"><span><b className="block text-xs text-slate-700">آمادگی گذرنامه</b><small className="mt-1 block text-[10px] text-slate-400">گذرنامه معتبر برای سفر خارجی دارم</small></span><input type="checkbox" checked={professional.passportReady} onChange={event=>set('passportReady',event.target.checked)} className="h-6 w-6 accent-emerald-700"/></label><div><label className="text-xs font-black text-slate-600">زبان‌های ارتباطی</label><div className="mt-2 flex rounded-2xl border border-slate-200 bg-slate-50 p-1"><input value={language} onChange={event=>setLanguage(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();const value=language.trim();if(value&&!professional.languages.includes(value)&&professional.languages.length<10){set('languages',[...professional.languages,value]);setLanguage('')}}}} placeholder="افزودن زبان و Enter" className="min-w-0 flex-1 bg-transparent px-3 text-xs outline-none"/><button type="button" onClick={()=>{const value=language.trim();if(value&&!professional.languages.includes(value)){set('languages',[...professional.languages,value]);setLanguage('')}}} className="rounded-xl bg-emerald-800 px-3 py-2 text-xs font-bold text-white">افزودن</button></div></div></div><div className="mt-4 flex flex-wrap gap-2">{professional.languages.map(item=><button key={item} type="button" onClick={()=>set('languages',professional.languages.filter(value=>value!==item))} className="rounded-full bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800 hover:bg-rose-50 hover:text-rose-600">{item} ×</button>)}</div><label className="mt-5 block text-xs font-black text-slate-600"><span className="flex items-center gap-2"><Backpack size={17}/>تجهیزات شخصی و محدودیت‌های عملیاتی</span><textarea value={professional.equipmentNotes} onChange={event=>set('equipmentNotes',event.target.value)} maxLength={500} rows={3} placeholder="تجهیزات موجود، نیاز به اجاره، محدودیت حمل بار یا نکات ضروری…" className="mt-2 w-full rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm outline-none focus:border-emerald-600"/><small className="mt-1 block text-left text-slate-400">{professional.equipmentNotes.length}/۵۰۰</small></label></section>
};

const SettingsWorkspace=({settings,onChange}:{settings:TravelProfile['settings'];onChange:(value:TravelProfile['settings'])=>void})=>{
  useEffect(()=>{document.documentElement.style.fontSize=settings.appearance.fontScale==='large'?'17px':'';document.documentElement.style.colorScheme=settings.appearance.theme==='system'?'light dark':settings.appearance.theme;document.documentElement.classList.toggle('reduce-motion',settings.appearance.reducedMotion);document.documentElement.classList.toggle('high-contrast',settings.appearance.highContrast);},[settings.appearance]);
  useEffect(()=>{localStorage.setItem('fc-motion-enabled',String(settings.preferences.autoPlayMedia));document.documentElement.classList.toggle('media-motion-disabled',!settings.preferences.autoPlayMedia);},[settings.preferences.autoPlayMedia]);
  const appearance=<K extends keyof TravelProfile['settings']['appearance']>(key:K,value:TravelProfile['settings']['appearance'][K])=>onChange({...settings,appearance:{...settings.appearance,[key]:value}});
  const notification=<K extends keyof TravelProfile['settings']['notifications']>(key:K,value:TravelProfile['settings']['notifications'][K])=>onChange({...settings,notifications:{...settings.notifications,[key]:value}});
  const preference=<K extends keyof TravelProfile['settings']['preferences']>(key:K,value:TravelProfile['settings']['preferences'][K])=>onChange({...settings,preferences:{...settings.preferences,[key]:value}});
  const security=<K extends keyof TravelProfile['settings']['security']>(key:K,value:TravelProfile['settings']['security'][K])=>onChange({...settings,security:{...settings.security,[key]:value}});
  return <div className="grid gap-6 xl:grid-cols-[1fr_1fr]"><SettingsPanel icon={MonitorCog} title="نمایش و دسترسی‌پذیری" subtitle="ظاهر پنل متناسب با شرایط استفاده"><div className="grid gap-4 sm:grid-cols-2"><Select label="حالت نمایش" value={settings.appearance.theme} options={['system','light','dark']} onChange={value=>appearance('theme',value as typeof settings.appearance.theme)}/><Select label="اندازه نوشته" value={settings.appearance.fontScale} options={['normal','large']} onChange={value=>appearance('fontScale',value as typeof settings.appearance.fontScale)}/></div><div className="mt-4 space-y-3"><SettingToggle title="کاهش حرکت تصاویر و انیمیشن‌ها" text="مناسب حساسیت حرکتی و مصرف کمتر باتری" checked={settings.appearance.reducedMotion} onChange={value=>appearance('reducedMotion',value)}/><SettingToggle title="کنتراست بیشتر" text="تفکیک بهتر مرزها و کنترل‌ها" checked={settings.appearance.highContrast} onChange={value=>appearance('highContrast',value)}/></div></SettingsPanel>
  <SettingsPanel icon={Bell} title="مرکز اعلان‌ها" subtitle="کانال و نوع پیام‌های دریافتی"><div className="grid gap-3 sm:grid-cols-2">{([['email','اعلان ایمیلی'],['sms','پیامک'],['push','اعلان مرورگر'],['booking','تغییرات رزرو'],['priceAlerts','هشدار کاهش قیمت'],['club','امتیاز باشگاه'],['community','فعالیت همسفران']] as const).map(([key,title])=><SettingToggle key={key} title={title} checked={settings.notifications[key]} onChange={value=>notification(key,value)}/>)}</div></SettingsPanel>
  <SettingsPanel icon={Languages} title="تنظیمات سفر و محتوا" subtitle="قالب محلی‌سازی و پخش رسانه"><div className="grid gap-4 sm:grid-cols-2"><Select label="زبان رابط" value={settings.preferences.language} options={['fa','en']} onChange={value=>preference('language',value as 'fa'|'en')}/><Select label="نوع تقویم" value={settings.preferences.calendar} options={['jalali','gregorian']} onChange={value=>preference('calendar',value as 'jalali'|'gregorian')}/></div><div className="mt-4"><SettingToggle title="پخش خودکار تصاویر موشن" text="برای اینترنت محدود می‌توانید غیرفعال کنید" checked={settings.preferences.autoPlayMedia} onChange={value=>preference('autoPlayMedia',value)}/></div></SettingsPanel>
  <SettingsPanel icon={ShieldCheck} title="کنترل‌های امنیتی" subtitle="مدیریت رفتارهای محافظتی حساب"><div className="space-y-3"><SettingToggle title="هشدار ورود جدید" text="اطلاع‌رسانی هنگام ورود از دستگاه تازه" checked={settings.security.loginAlerts} onChange={value=>security('loginAlerts',value)}/><SettingToggle title="درخواست فعال‌سازی ورود دومرحله‌ای" text="ثبت درخواست تا زمان اتصال سرویس OTP" checked={settings.security.twoFactorRequested} onChange={value=>security('twoFactorRequested',value)}/><SettingToggle title="پنهان‌کردن مبالغ حساس" text="مبالغ کیف پول در محیط‌های عمومی پوشانده شوند" checked={settings.security.hideSensitiveAmounts} onChange={value=>security('hideSensitiveAmounts',value)}/></div><div className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-xs leading-6 text-amber-800">فعال‌سازی نهایی ورود دومرحله‌ای پس از اتصال سرویس پیامک انجام می‌شود؛ این گزینه فعلاً درخواست شما را ثبت می‌کند.</div></SettingsPanel></div>
};
const SettingsPanel=({icon:Icon,title,subtitle,children}:{icon:React.ElementType;title:string;subtitle:string;children:React.ReactNode})=><section className="rounded-[28px] border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><SectionTitle icon={Icon} title={title} subtitle={subtitle}/><div className="mt-6">{children}</div></section>;
const SettingToggle=({title,text,checked,onChange}:{key?:React.Key;title:string;text?:string;checked:boolean;onChange:(value:boolean)=>void})=><label className="flex cursor-pointer items-center justify-between gap-4 rounded-2xl border border-slate-200 bg-slate-50 p-4 transition hover:border-emerald-300"><span><b className="block text-xs text-slate-700">{title}</b>{text&&<small className="mt-1 block text-[10px] leading-5 text-slate-400">{text}</small>}</span><span className={`relative h-7 w-12 shrink-0 rounded-full transition ${checked?'bg-emerald-700':'bg-slate-300'}`}><input type="checkbox" checked={checked} onChange={event=>onChange(event.target.checked)} className="sr-only"/><i className={`absolute top-1 h-5 w-5 rounded-full bg-white shadow transition ${checked?'right-6':'right-1'}`}/></span></label>;

const WalletWorkspace=({profile,onChange,onNotice}:{profile:TravelProfile;onChange:(wallet:TravelProfile['wallet'])=>void;onNotice:(notice:{type:'ok'|'error';text:string}|null)=>void})=>{
  const [mode,setMode]=useState<'topup'|'withdraw'>('topup'); const [amount,setAmount]=useState(''); const [source,setSource]=useState('کارت بانکی به نام صاحب حساب'); const [submitting,setSubmitting]=useState(false); const [query,setQuery]=useState(''); const [typeFilter,setTypeFilter]=useState<'all'|'credit'|'debit'>('all');
  const numericAmount=Number(amount.replace(/[^0-9]/g,''));
  const transactions=useMemo(()=>profile.wallet.transactions.filter(item=>(typeFilter==='all'||item.type===typeFilter)&&(`${item.title} ${item.reference}`).toLowerCase().includes(query.trim().toLowerCase())),[profile.wallet.transactions,query,typeFilter]);
  const monthlyCredit=profile.wallet.transactions.filter(item=>item.type==='credit'&&new Date(item.date).getMonth()===new Date().getMonth()).reduce((sum,item)=>sum+item.amount,0);
  const monthlyDebit=profile.wallet.transactions.filter(item=>item.type==='debit'&&new Date(item.date).getMonth()===new Date().getMonth()).reduce((sum,item)=>sum+item.amount,0);
  const submit=async()=>{if(numericAmount<10000)return onNotice({type:'error',text:'حداقل مبلغ عملیات ۱۰٬۰۰۰ تومان است.'});if(source.trim().length<2)return onNotice({type:'error',text:'مبدأ یا مقصد تسویه را مشخص کنید.'});setSubmitting(true);onNotice(null);try{const result=await profileApi.walletOperation({action:mode,amount:numericAmount,sourceLabel:source.trim()});onChange(result.wallet);setAmount('');onNotice({type:'ok',text:`عملیات با موفقیت ثبت شد. شماره پیگیری: ${result.transaction.reference}`});}catch(error){onNotice({type:'error',text:error instanceof Error?error.message:'عملیات مالی انجام نشد.'});}finally{setSubmitting(false)}};
  const exportCsv=()=>{const rows=[['reference','date','title','type','amount','status'],...transactions.map(item=>[item.reference,item.date,item.title,item.type,String(item.amount),item.status])];const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`friendly-wallet-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(link.href)};
  return <div className="space-y-6">
    <section className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <div className="relative overflow-hidden rounded-[32px] bg-gradient-to-br from-[#071e26] via-[#0b4a41] to-[#13715c] p-6 text-white shadow-2xl sm:p-8"><div className="absolute -left-16 -top-20 h-64 w-64 rounded-full bg-lime-300/15 blur-3xl"/><div className="relative"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold text-emerald-200">FRIENDLY PAY · کیف پول سفر</p><p className="mt-4 text-sm text-white/55">موجودی قابل استفاده</p><h3 className="mt-1 text-3xl font-black sm:text-5xl">{profile.wallet.balance.toLocaleString('fa-IR')} <small className="text-base text-white/70">تومان</small></h3></div><div className="grid h-14 w-14 place-items-center rounded-2xl border border-white/15 bg-white/10"><WalletCards className="text-lime-300" size={28}/></div></div><div className="mt-9 grid grid-cols-2 gap-3 sm:grid-cols-3"><WalletMetric label="مسدودی رزرو" value={profile.wallet.lockedBalance||0}/><WalletMetric label="ورودی این ماه" value={monthlyCredit}/><WalletMetric label="خروجی این ماه" value={monthlyDebit}/></div><div className="mt-7 flex flex-wrap items-center justify-between gap-3 border-t border-white/10 pt-5 text-[11px] text-white/55"><span className="flex items-center gap-2"><ShieldCheck size={15} className="text-lime-300"/>دفترکل امن و ثبت شماره پیگیری</span><span>آخرین بروزرسانی: {new Date(profile.updatedAt).toLocaleDateString('fa-IR')}</span></div></div></div>
      <div className="rounded-[32px] border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="flex rounded-2xl bg-slate-100 p-1"><button onClick={()=>setMode('topup')} className={`flex-1 rounded-xl py-3 text-sm font-black transition ${mode==='topup'?'bg-emerald-800 text-white shadow':'text-slate-500'}`}>افزایش موجودی</button><button onClick={()=>setMode('withdraw')} className={`flex-1 rounded-xl py-3 text-sm font-black transition ${mode==='withdraw'?'bg-emerald-800 text-white shadow':'text-slate-500'}`}>درخواست برداشت</button></div><div className="mt-6"><label className="text-xs font-black text-slate-600">مبلغ به تومان<div className="mt-2 flex items-center rounded-2xl border border-slate-200 bg-slate-50 px-4 focus-within:border-emerald-600"><input inputMode="numeric" value={amount} onChange={e=>setAmount(e.target.value.replace(/[^0-9]/g,''))} placeholder="مثلاً ۵۰۰٬۰۰۰" className="w-full bg-transparent py-4 text-lg font-black outline-none"/><span className="text-xs text-slate-400">تومان</span></div></label><div className="mt-3 grid grid-cols-3 gap-2">{[500000,1000000,2000000].map(value=><button key={value} onClick={()=>setAmount(String(value))} className="rounded-xl border border-slate-200 py-2 text-[11px] font-bold text-slate-600 hover:border-emerald-500 hover:text-emerald-700">{value.toLocaleString('fa-IR')}</button>)}</div><label className="mt-5 block text-xs font-black text-slate-600">{mode==='topup'?'روش پرداخت':'شبای مقصد یا حساب ثبت‌شده'}<input value={source} onChange={e=>setSource(e.target.value)} maxLength={80} className="mt-2 w-full rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm outline-none focus:border-emerald-600"/></label><button onClick={submit} disabled={submitting||numericAmount<10000} className="mt-5 flex w-full items-center justify-center gap-2 rounded-2xl bg-lime-300 py-4 text-sm font-black text-emerald-950 shadow-lg shadow-lime-200 disabled:cursor-not-allowed disabled:opacity-50">{submitting?<LoaderCircle className="animate-spin" size={19}/>:<BadgeCheck size={19}/>} {mode==='topup'?'ثبت و افزایش موجودی':'ثبت درخواست برداشت'}</button><p className="mt-3 text-center text-[10px] leading-5 text-slate-400">اطلاعات کامل کارت ذخیره نمی‌شود. برداشت تنها تا سقف موجودی قابل استفاده امکان‌پذیر است.</p></div></div>
    </section>
    <section className="overflow-hidden rounded-[30px] border border-slate-200 bg-white shadow-sm"><div className="flex flex-col gap-4 border-b border-slate-100 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-7"><div><h3 className="font-black text-slate-900">صورتحساب و گردش مالی</h3><p className="mt-1 text-xs text-slate-400">جستجو، کنترل وضعیت و دریافت خروجی حسابداری</p></div><div className="flex flex-wrap gap-2"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="جستجوی شرح یا پیگیری" className="min-w-52 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs outline-none focus:border-emerald-500"/><select value={typeFilter} onChange={e=>setTypeFilter(e.target.value as typeof typeFilter)} className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs"><option value="all">همه تراکنش‌ها</option><option value="credit">ورودی</option><option value="debit">خروجی</option></select><button onClick={exportCsv} disabled={!transactions.length} className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2 text-xs font-black text-emerald-800 disabled:opacity-40">خروجی CSV</button></div></div>
      {!transactions.length?<div className="p-12 text-center"><Route className="mx-auto text-slate-300" size={40}/><h4 className="mt-4 font-black text-slate-700">تراکنشی مطابق فیلتر وجود ندارد</h4><p className="mt-2 text-xs text-slate-400">پس از اولین عملیات، ریز گردش کیف پول در این بخش ثبت می‌شود.</p></div>:<div className="overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="bg-slate-50 text-[11px] text-slate-400"><tr><th className="p-4 sm:px-7">شرح تراکنش</th><th className="p-4">تاریخ</th><th className="p-4">شماره پیگیری</th><th className="p-4">وضعیت</th><th className="p-4 sm:px-7">مبلغ</th></tr></thead><tbody>{transactions.map(item=><tr key={item.id} className="border-t border-slate-100 hover:bg-emerald-50/30"><td className="p-4 sm:px-7"><b className="block text-slate-800">{item.title}</b><small className="text-slate-400">{item.category}</small></td><td className="p-4 text-xs text-slate-500">{new Date(item.date).toLocaleString('fa-IR')}</td><td className="p-4 font-mono text-xs text-slate-500" dir="ltr">{item.reference}</td><td className="p-4"><span className={`rounded-full px-3 py-1 text-[10px] font-black ${item.status==='موفق'?'bg-emerald-100 text-emerald-700':item.status==='ناموفق'?'bg-rose-100 text-rose-700':'bg-amber-100 text-amber-700'}`}>{item.status}</span></td><td className={`p-4 font-black sm:px-7 ${item.type==='credit'?'text-emerald-600':'text-rose-600'}`} dir="ltr">{item.type==='credit'?'+':'−'} {item.amount.toLocaleString('fa-IR')}</td></tr>)}</tbody></table></div>}
    </section>
  </div>
};
const WalletMetric=({label,value}:{label:string;value:number})=><div className="rounded-2xl border border-white/10 bg-white/5 p-3 backdrop-blur"><p className="text-[10px] text-white/45">{label}</p><b className="mt-1 block text-sm">{value.toLocaleString('fa-IR')}</b></div>;

const HeroMetric=({value,label}:{value:string;label:string})=><div className="min-w-24 rounded-2xl border border-white/10 bg-white/10 p-3 text-center backdrop-blur"><b className="block text-xl text-lime-300">{value}</b><small className="text-[10px] text-white/55">{label}</small></div>;
const SectionTitle=({icon:Icon,title,subtitle}:{icon:React.ElementType;title:string;subtitle:string})=><div className="flex items-start gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-emerald-100 text-emerald-700"><Icon size={21}/></div><div><h3 className="font-black text-slate-900">{title}</h3><p className="mt-1 text-xs text-slate-400">{subtitle}</p></div></div>;
const Field=({label,value,onChange,type='text',disabled=false,icon:Icon}:{label:string;value:string;onChange?:(v:string)=>void;type?:string;disabled?:boolean;icon?:React.ElementType})=><label className="block text-xs font-black text-slate-600">{label}<div className="relative mt-2">{Icon&&<Icon className="absolute right-3 top-3.5 text-slate-400" size={17}/>}<input type={type} value={value} disabled={disabled} onChange={e=>onChange?.(e.target.value)} className={`w-full rounded-2xl border border-slate-200 bg-slate-50 p-3 text-sm outline-none focus:border-emerald-600 focus:bg-white disabled:text-slate-400 ${Icon?'pr-10':''}`}/></div></label>;
const Select=({label,value,options,onChange}:{label:string;value:string;options:string[];onChange:(v:string)=>void})=><label className="block text-xs font-black text-slate-600">{label}<select value={value} onChange={e=>onChange(e.target.value)} className="mt-2 w-full rounded-2xl border border-slate-200 bg-slate-50 p-3 text-sm outline-none focus:border-emerald-600">{options.map(option=><option key={option}>{option}</option>)}</select></label>;
const StatCard=({icon:Icon,value,label,tone}:{icon:React.ElementType;value:string;label:string;tone:'lime'|'amber'|'cyan'})=>{const colors={lime:'bg-lime-100 text-lime-700',amber:'bg-amber-100 text-amber-700',cyan:'bg-cyan-100 text-cyan-700'};return <div className="rounded-[24px] border bg-white p-5"><div className={`grid h-11 w-11 place-items-center rounded-2xl ${colors[tone]}`}><Icon/></div><p className="mt-5 text-2xl font-black">{value}</p><p className="mt-1 text-xs text-slate-400">{label}</p></div>};
const Empty=({show,icon:Icon,title,text,wide=false}:{show:boolean;icon:React.ElementType;title:string;text:string;wide?:boolean})=>show?<div className={`mt-5 rounded-[24px] border-2 border-dashed border-slate-200 bg-white p-10 text-center ${wide?'sm:col-span-2 lg:col-span-3':''}`}><Icon className="mx-auto text-slate-300" size={38}/><h4 className="mt-4 font-black text-slate-700">{title}</h4><p className="mx-auto mt-2 max-w-sm text-xs leading-6 text-slate-400">{text}</p></div>:null;
